block.css:
/* Jede Art setzt nur --ton. Die Signalfarbe wird mit der Textfarbe des Kits gemischt –
   so bleibt sie auf hellen und dunklen Flächen lesbar. */
.box {
  --ton: var(--cb-accent);
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  padding: 1.25rem 1.5rem;
  border: 1px solid var(--cb-line);
  border-inline-start: .375rem solid var(--ton);
  border-radius: var(--cb-radius);
  background: var(--cb-surface);
  background: color-mix(in srgb, var(--ton) 9%, var(--cb-surface));
}
.box--warnung { --ton: color-mix(in srgb, #D97706 78%, currentColor); }
.box--erfolg { --ton: color-mix(in srgb, #16A34A 72%, currentColor); }
.box__icon { flex: none; display: inline-flex; color: var(--ton); font-size: 1.75rem; line-height: 1; }
.box__body { min-width: 0; }
.box__title { margin: 0 0 .35rem; font-size: 1.2rem; line-height: 1.3; }
.box__text > :first-child { margin-top: 0; }
.box__text > :last-child { margin-bottom: 0; }
@media (max-width: 30rem) {
  .box { flex-direction: column; gap: .5rem; padding: 1rem 1.1rem; }
}
